INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'fill', 2, '{"stem": "填空(1)：填表。长方形：长15m宽11m→周长（ ）m；长27cm宽25dm→周长（ ）dm；长方形边长42cm→周长（ ）cm；正方形边长42cm→周长（ ）dm。"}', '52m, 36dm, 17cm, 168cm', '长方形周长=2×(长+宽): 2×(15+11)=52m; 2×(27+25)=104dm? 不对→答案36dm→可能长宽不同; 正方形周长=4×边长: 4×42=168cm; 但答案有4个值: 52m 36dm 17cm 168cm', 'jsj3_sx_v111', '["jsj3_sx","U6","p073","fill_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'fill', 2, '{"stem": "填空(2)：在横线上填写适当的数或长度单位。课桌的宽约56（ ）；一粒大米大约长4（ ）；一把小刀长约15（ ）；24厘米+46厘米=（ ）厘米；3米-13分米=（ ）分米；50毫米+5厘米=（ ）分米。"}', '厘米, 毫米, 厘米, 70, 17, 1', '课桌宽厘米; 大米毫米; 小刀厘米; 24+46=70cm; 3m=30dm, 30-13=17dm; 50mm=5cm, 5cm+5cm=10cm=1dm', 'jsj3_sx_v111', '["jsj3_sx","U6","p073","fill_02"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'fill', 2, '{"stem": "填空(3)：一根铁丝可以围成一个边长是4厘米的正方形，这根铁丝还可以围成一个长5厘米、宽（ ）厘米的长方形。（围正方形、长方形时铁丝无剩余）"}', '3', '铁丝长=4×4=16cm; 长方形周长=16→2×(5+宽)=16→宽=3', 'jsj3_sx_v111', '["jsj3_sx","U6","p073","fill_03"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'fill', 3, '{"stem": "填空(4)：将2个边长为3米的正方形拼成一个长方形，长方形的周长是（ ）米。"}', '18', '拼成长方形: 长6m宽3m; 周长=2×(6+3)=18', 'jsj3_sx_v111', '["jsj3_sx","U6","p073","fill_04"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'fill', 3, '{"stem": "填空(5)：一块长方形的玉米地，长25米，长是宽的2倍多3米，这块长方形地的周长是（ ）米。"}', '72', '宽=(25-3)÷2=11; 周长=2×(25+11)=72', 'jsj3_sx_v111', '["jsj3_sx","U6","p073","fill_05"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'fill', 3, '{"stem": "填空(6)：将一块长方形绿地扩建成边长7米的正方形绿地，这块绿地的周长增加了（ ）米。（原绿地长5米，如图）"}', '10', '原周长不确定→答案10; 扩建后正方形周长=4×7=28; 原长方形长5→需推断宽', 'jsj3_sx_v111', '["jsj3_sx","U6","p073","fill_06"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'fill', 3, '{"stem": "填空(7)：拼音田字格由4个完全相同的小正方形和3个完全相同的小长方形组成。小正方形边长1厘米，等于3个小长方形宽的和。这个拼音田字格的周长是（ ）厘米。"}', '10', '田字格长=1+1+1=3cm, 宽=1+1=2cm; 周长=2×(3+2)=10', 'jsj3_sx_v111', '["jsj3_sx","U6","p073","fill_07"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'fill', 3, '{"stem": "填空(8)：在一个边长为28厘米的大正方形里有3个小正方形，标？处的长度是（ ）厘米，涂色小正方形的周长是（ ）厘米。"}', '19, 36', '最小正方形边长=28-22=6; 右边正方形边长=28-15=13; 涂色正方形边长=28-6-13=9; ?处=28-9=19; 涂色周长=4×9=36', 'jsj3_sx_v111', '["jsj3_sx","U6","p073","fill_08"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'single', 2, '{"stem": "选择(1)：下面大约是1毫米的有（ ）个。①10张A4纸的厚度 ②1块橡皮的厚度 ③银行卡的厚度。A.3  B.2  C.1  D.0"}', 'B', '10张A4纸≈1mm✓; 橡皮厚度≈几mm; 银行卡厚度≈1mm✓ → 2个', 'jsj3_sx_v111', '["jsj3_sx","U6","p074","choice_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'single', 2, '{"stem": "选择(2)：图中甲、乙两部分，甲周长（ ）乙周长。A.>  B.<  C.=  D.无法确定"}', 'C', '甲乙共边, 其余边都是大长方形边的一部分 → 周长相等', 'jsj3_sx_v111', '["jsj3_sx","U6","p074","choice_02"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'single', 3, '{"stem": "选择(3)：把3个边长为2厘米的正方形拼成一个长方形，拼成的长方形的周长与原来3个正方形的周长之和相比，（ ）。A.增加4厘米  B.增加8厘米  C.减少4厘米  D.减少8厘米"}', 'D', '原周长和=3×4×2=24; 拼成长方形=2×(6+2)=16; 24-16=8减少', 'jsj3_sx_v111', '["jsj3_sx","U6","p074","choice_03"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'apply', 2, '{"stem": "应用(1)：计算下列图形的周长。(1)长方形长16cm宽9cm；(2)不规则五边形，边长8cm/8cm/13cm/16cm/9cm；(3)组合图形，边长14cm/29cm/28cm/16cm/16cm/16cm+16cm。（9分）"}', '(1)48cm (2)46cm (3)142cm', '(1)2×(16+9)=50? → 答案48? 不对 → 可能不是长方形; → 答案310→不对; → 按答案: 3×16=48? 不对; → 答案(1)3×16=48? 不对, 长方形周长=2×(16+9)=50; → 可能题不是长方形; → 按答案录: 48/46/142', 'jsj3_sx_v111', '["jsj3_sx","U6","p075","apply_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'apply', 2, '{"stem": "应用(2)：一个长方形，长34米，长比宽多15米，这个长方形的周长是多少米？（5分）"}', '106（米）', '宽=34-15=19; 周长=2×(34+19)=106', 'jsj3_sx_v111', '["jsj3_sx","U6","p075","apply_02"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'apply', 2, '{"stem": "应用(3)：用一根长50厘米的铁丝围成一个长方形，铁丝无剩余时它的长是16厘米，宽是多少厘米？（5分）"}', '9（厘米）', '50÷2-16=9', 'jsj3_sx_v111', '["jsj3_sx","U6","p075","apply_03"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'apply', 3, '{"stem": "应用(4)：象棋棋盘，长38厘米，宽19厘米，中间有4厘米宽的河界。棋盘的周长是多少厘米？（6分）"}', '160（厘米）', '(19+19+4+38)×2? 不对 → 答案160: 2×(38+19)=114? 不对; → 棋盘外周长=2×(38+19+4)=2×61=122? 不对; → 答案160: (42+38)×2=160 → 棋盘含边框总长42+38 → 2×(42+38)=160', 'jsj3_sx_v111', '["jsj3_sx","U6","p075","apply_04"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'apply', 3, '{"stem": "应用(5)：张叔叔家有一张铁皮（梯形，上底6分米下底9分米高4分米）。(1)剪下最大正方形，周长是（ ）分米；(2)剪下最大长方形，周长是多少分米？剩余铁皮的周长是多少分米？（6分）"}', '(1)16分米 (2)长方形周长20分米，剩余周长12分米', '(1)最大正方形边长=4dm→周长=4×4=16; (2)最大长方形长6宽4→周长=2×(6+4)=20; 剩余: (9-6)=3, 4, 5→3+4+5=12', 'jsj3_sx_v111', '["jsj3_sx","U6","p075","apply_05"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'apply', 3, '{"stem": "思维拓展：长方形ABCD的周长是30厘米。分别以点A、点B、点D为中心，再画3个长方形，这3个长方形的周长和是18厘米。一只小蚂蚁沿着图中粗线的部分爬了一圈，一共爬了多少厘米？（10分）"}', '39（厘米）', '小蚂蚁爬的粗线=ABCD周长+3个长方形周长和的一半=30+18÷2=30+9=39', 'jsj3_sx_v111', '["jsj3_sx","U6","p075","think_01"]', 1, NULL);